mkitem!{mkstruct!{#[doc = " The underlying representation of leaf nodes and part of the representation of internal nodes."] struct LeafNode < K , V > { #[doc = " We want to be covariant in `K` and `V`."] parent : Option < NonNull < InternalNode < K , V > > > , #[doc = " This node's index into the parent node's `edges` array."] #[doc = " `*node.parent.edges[node.parent_idx]` should be the same thing as `node`."] #[doc = " This is only guaranteed to be initialized when `parent` is non-null."] parent_idx : MaybeUninit < u16 > , #[doc = " The number of keys and values this node stores."] len : u16 , #[doc = " The arrays storing the actual data of the node. Only the first `len` elements of each"] #[doc = " array are initialized and valid."] keys : [MaybeUninit < K > ; CAPACITY] , vals : [MaybeUninit < V > ; CAPACITY] , }}}
mkitem!{mkimpl!{impl < K , V > LeafNode < K , V > { #[doc = " Initializes a new `LeafNode` in-place."] unsafe fn init (this : * mut Self) { unsafe { (& raw mut (* this) . parent) . write (None) ; (& raw mut (* this) . len) . write (0) ; } } #[doc = " Creates a new boxed `LeafNode`."] fn new < A : Allocator + Clone > (alloc : A) -> Box < Self , A > { unsafe { let mut leaf = Box :: new_uninit_in (alloc) ; LeafNode :: init (leaf . as_mut_ptr ()) ; leaf . assume_init () } } }}}
mkitem!{mkstruct!{#[doc = " The underlying representation of internal nodes. As with `LeafNode`s, these should be hidden"] #[doc = " behind `BoxedNode`s to prevent dropping uninitialized keys and values. Any pointer to an"] #[doc = " `InternalNode` can be directly cast to a pointer to the underlying `LeafNode` portion of the"] #[doc = " node, allowing code to act on leaf and internal nodes generically without having to even check"] #[doc = " which of the two a pointer is pointing at. This property is enabled by the use of `repr(C)`."] #[repr (C)] struct InternalNode < K , V > { data : LeafNode < K , V > , #[doc = " The pointers to the children of this node. `len + 1` of these are considered"] #[doc = " initialized and valid, except that near the end, while the tree is held"] #[doc = " through borrow type `Dying`, some of these pointers are dangling."] edges : [MaybeUninit < BoxedNode < K , V > > ; 2 * B] , }}}
mkitem!{mkimpl!{impl < K , V > InternalNode < K , V > { #[doc = " Creates a new boxed `InternalNode`."] #[doc = ""] #[doc = " # Safety"] #[doc = " An invariant of internal nodes is that they have at least one"] #[doc = " initialized and valid edge. This function does not set up"] #[doc = " such an edge."] unsafe fn new < A : Allocator + Clone > (alloc : A) -> Box < Self , A > { unsafe { let mut node = Box :: < Self , _ > :: new_uninit_in (alloc) ; LeafNode :: init (& raw mut (* node . as_mut_ptr ()) . data) ; node . assume_init () } } }}}
mkitem!{#[doc = " A managed, non-null pointer to a node. This is either an owned pointer to"] #[doc = " `LeafNode<K, V>` or an owned pointer to `InternalNode<K, V>`."] #[doc = ""] #[doc = " However, `BoxedNode` contains no information as to which of the two types"] #[doc = " of nodes it actually contains, and, partially due to this lack of information,"] #[doc = " is not a separate type and has no destructor."] type BoxedNode < K , V > = NonNull < LeafNode < K , V > > ;}
mkitem!{mkstruct!{#[doc = ""] #[doc = " A reference to a node."] #[doc = ""] #[doc = " This type has a number of parameters that controls how it acts:"] #[doc = " - `BorrowType`: A dummy type that describes the kind of borrow and carries a lifetime."] #[doc = "    - When this is `Immut<'a>`, the `NodeRef` acts roughly like `&'a Node`."] #[doc = "    - When this is `ValMut<'a>`, the `NodeRef` acts roughly like `&'a Node`"] #[doc = "      with respect to keys and tree structure, but also allows many"] #[doc = "      mutable references to values throughout the tree to coexist."] #[doc = "    - When this is `Mut<'a>`, the `NodeRef` acts roughly like `&'a mut Node`,"] #[doc = "      although insert methods allow a mutable pointer to a value to coexist."] #[doc = "    - When this is `Owned`, the `NodeRef` acts roughly like `Box<Node>`,"] #[doc = "      but does not have a destructor, and must be cleaned up manually."] #[doc = "    - When this is `Dying`, the `NodeRef` still acts roughly like `Box<Node>`,"] #[doc = "      but has methods to destroy the tree bit by bit, and ordinary methods,"] #[doc = "      while not marked as unsafe to call, can invoke UB if called incorrectly."] #[doc = "   Since any `NodeRef` allows navigating through the tree, `BorrowType`"] #[doc = "   effectively applies to the entire tree, not just to the node itself."] #[doc = " - `K` and `V`: These are the types of keys and values stored in the nodes."] #[doc = " - `Type`: This can be `Leaf`, `Internal`, or `LeafOrInternal`. When this is"] #[doc = "   `Leaf`, the `NodeRef` points to a leaf node, when this is `Internal` the"] #[doc = "   `NodeRef` points to an internal node, and when this is `LeafOrInternal` the"] #[doc = "   `NodeRef` could be pointing to either type of node."] #[doc = "   `Type` is named `NodeType` when used outside `NodeRef`."] #[doc = ""] #[doc = " Both `BorrowType` and `NodeType` restrict what methods we implement, to"] #[doc = " exploit static type safety. There are limitations in the way we can apply"] #[doc = " such restrictions:"] #[doc = " - For each type parameter, we can only define a method either generically"] #[doc = "   or for one particular type. For example, we cannot define a method like"] #[doc = "   `into_kv` generically for all `BorrowType`, or once for all types that"] #[doc = "   carry a lifetime, because we want it to return `&'a` references."] #[doc = "   Therefore, we define it only for the least powerful type `Immut<'a>`."] #[doc = " - We cannot get implicit coercion from say `Mut<'a>` to `Immut<'a>`."] #[doc = "   Therefore, we have to explicitly call `reborrow` on a more powerful"] #[doc = "   `NodeRef` in order to reach a method like `into_kv`."] #[doc = ""] #[doc = " All methods on `NodeRef` that return some kind of reference, either:"] #[doc = " - Take `self` by value, and return the lifetime carried by `BorrowType`."] #[doc = "   Sometimes, to invoke such a method, we need to call `reborrow_mut`."] #[doc = " - Take `self` by reference, and (implicitly) return that reference's"] #[doc = "   lifetime, instead of the lifetime carried by `BorrowType`. That way,"] #[doc = "   the borrow checker guarantees that the `NodeRef` remains borrowed as long"] #[doc = "   as the returned reference is used."] #[doc = "   The methods supporting insert bend this rule by returning a raw pointer,"] #[doc = "   i.e., a reference without any lifetime."] pub (super) struct NodeRef < BorrowType , K , V , Type > { #[doc = " The number of levels that the node and the level of leaves are apart, a"] #[doc = " constant of the node that cannot be entirely described by `Type`, and that"] #[doc = " the node itself does not store. We only need to store the height of the root"] #[doc = " node, and derive every other node's height from it."] #[doc = " Must be zero if `Type` is `Leaf` and non-zero if `Type` is `Internal`."] height : usize , #[doc = " The pointer to the leaf or internal node. The definition of `InternalNode`"] #[doc = " ensures that the pointer is valid either way."] node : NonNull < LeafNode < K , V > > , _marker : PhantomData < (BorrowType , Type) > , }}}
