mkitem!{mkimpl!{impl < BorrowType , K , V , Type > NodeRef < BorrowType , K , V , Type > { #[doc = " Finds the length of the node. This is the number of keys or values."] #[doc = " The number of edges is `len() + 1`."] #[doc = " Note that, despite being safe, calling this function can have the side effect"] #[doc = " of invalidating mutable references that unsafe code has created."] pub (super) fn len (& self) -> usize { unsafe { usize :: from ((* Self :: as_leaf_ptr (self)) . len) } } #[doc = " Returns the number of levels that the node and leaves are apart. Zero"] #[doc = " height means the node is a leaf itself. If you picture trees with the"] #[doc = " root on top, the number says at which elevation the node appears."] #[doc = " If you picture trees with leaves on top, the number says how high"] #[doc = " the tree extends above the node."] pub (super) fn height (& self) -> usize { self . height } #[doc = " Temporarily takes out another, immutable reference to the same node."] pub (super) fn reborrow (& self) -> NodeRef < marker :: Immut < '_ > , K , V , Type > { NodeRef { height : self . height , node : self . node , _marker : PhantomData } } #[doc = " Exposes the leaf portion of any leaf or internal node."] #[doc = ""] #[doc = " Returns a raw ptr to avoid invalidating other references to this node."] fn as_leaf_ptr (this : & Self) -> * mut LeafNode < K , V > { this . node . as_ptr () } }}}
mkitem!{mkimpl!{impl < BorrowType : marker :: BorrowType , K , V , Type > NodeRef < BorrowType , K , V , Type > { #[doc = " Finds the parent of the current node. Returns `Ok(handle)` if the current"] #[doc = " node actually has a parent, where `handle` points to the edge of the parent"] #[doc = " that points to the current node. Returns `Err(self)` if the current node has"] #[doc = " no parent, giving back the original `NodeRef`."] #[doc = ""] #[doc = " The method name assumes you picture trees with the root node on top."] #[doc = ""] #[doc = " `edge.descend().ascend().unwrap()` and `node.ascend().unwrap().descend()` should"] #[doc = " both, upon success, do nothing."] pub (super) fn ascend (self ,) -> Result < Handle < NodeRef < BorrowType , K , V , marker :: Internal > , marker :: Edge > , Self > { const { assert ! (BorrowType :: TRAVERSAL_PERMIT) ; } let leaf_ptr : * const _ = Self :: as_leaf_ptr (& self) ; unsafe { (* leaf_ptr) . parent } . as_ref () . map (| parent | Handle { node : NodeRef :: from_internal (* parent , self . height + 1) , idx : unsafe { usize :: from ((* leaf_ptr) . parent_idx . assume_init ()) } , _marker : PhantomData , }) . ok_or (self) } pub (super) fn first_edge (self) -> Handle < Self , marker :: Edge > { unsafe { Handle :: new_edge (self , 0) } } pub (super) fn last_edge (self) -> Handle < Self , marker :: Edge > { let len = self . len () ; unsafe { Handle :: new_edge (self , len) } } #[doc = " Note that `self` must be nonempty."] pub (super) fn first_kv (self) -> Handle < Self , marker :: KV > { let len = self . len () ; assert ! (len > 0) ; unsafe { Handle :: new_kv (self , 0) } } #[doc = " Note that `self` must be nonempty."] pub (super) fn last_kv (self) -> Handle < Self , marker :: KV > { let len = self . len () ; assert ! (len > 0) ; unsafe { Handle :: new_kv (self , len - 1) } } }}}
